-- Comanda Llena v1: isolated SaaS data model. Applied to Supabase as migration 20260812203306.
create table if not exists public.comanda_accounts (
  id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique,
  owner_id uuid not null references auth.users(id) on delete cascade,
  status text not null default 'trial' check (status in ('trial','active','past_due','suspended','cancelled')),
  trial_started_at timestamptz not null default now(), trial_ends_at timestamptz not null default (now()+interval '14 days'),
  timezone text not null default 'America/Argentina/Buenos_Aires', onboarding_completed boolean not null default false,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.comanda_members (account_id uuid not null references public.comanda_accounts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'owner' check(role in('owner','admin','operator','viewer')),created_at timestamptz not null default now(),primary key(account_id,user_id));
create table if not exists public.comanda_branches (id uuid primary key default gen_random_uuid(),account_id uuid not null references public.comanda_accounts(id) on delete cascade,name text not null,active boolean not null default true,created_at timestamptz not null default now(),unique(account_id,name));
create table if not exists public.comanda_staff (id uuid primary key default gen_random_uuid(),account_id uuid not null references public.comanda_accounts(id) on delete cascade,branch_id uuid references public.comanda_branches(id) on delete cascade,name text not null,staff_type text not null check(staff_type in('admin','waiter','cashier','cook','bar','other')),phone text,email text,active boolean not null default true,permissions jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.comanda_cash_registers (id uuid primary key default gen_random_uuid(),account_id uuid not null references public.comanda_accounts(id) on delete cascade,branch_id uuid not null references public.comanda_branches(id) on delete cascade,name text not null,active boolean not null default true,created_at timestamptz not null default now(),unique(branch_id,name));
create table if not exists public.comanda_cash_sessions (id uuid primary key default gen_random_uuid(),account_id uuid not null references public.comanda_accounts(id) on delete cascade,register_id uuid not null references public.comanda_cash_registers(id) on delete cascade,staff_id uuid references public.comanda_staff(id) on delete set null,opened_by uuid not null references auth.users(id) on delete restrict,opened_at timestamptz not null default now(),opening_amount numeric(14,2) not null default 0,status text not null default 'open' check(status in('open','closed')),closed_by uuid references auth.users(id) on delete restrict,closed_at timestamptz,closing_amount numeric(14,2),notes text);
create table if not exists public.comanda_sectors (id uuid primary key default gen_random_uuid(),account_id uuid not null references public.comanda_accounts(id) on delete cascade,branch_id uuid not null references public.comanda_branches(id) on delete cascade,name text not null,sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),unique(branch_id,name));
create table if not exists public.comanda_tables (id uuid primary key default gen_random_uuid(),account_id uuid not null references public.comanda_accounts(id) on delete cascade,branch_id uuid not null references public.comanda_branches(id) on delete cascade,sector_id uuid not null references public.comanda_sectors(id) on delete cascade,number text not null,name text,seats integer not null default 4 check(seats>0 and seats<=100),pos_x integer not null default 0,pos_y integer not null default 0,width integer not null default 1 check(width between 1 and 4),height integer not null default 1 check(height between 1 and 4),active boolean not null default true,created_at timestamptz not null default now(),unique(sector_id,number));
create table if not exists public.comanda_categories (id uuid primary key default gen_random_uuid(),account_id uuid not null references public.comanda_accounts(id) on delete cascade,branch_id uuid references public.comanda_branches(id) on delete cascade,name text not null,color text not null default '#e7f7f2',sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.comanda_products (id uuid primary key default gen_random_uuid(),account_id uuid not null references public.comanda_accounts(id) on delete cascade,category_id uuid not null references public.comanda_categories(id) on delete cascade,name text not null,description text,price numeric(14,2) not null default 0 check(price>=0),destination text not null default 'kitchen' check(destination in('kitchen','bar','none')),active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.comanda_orders (id uuid primary key default gen_random_uuid(),account_id uuid not null references public.comanda_accounts(id) on delete cascade,branch_id uuid not null references public.comanda_branches(id) on delete cascade,table_id uuid references public.comanda_tables(id) on delete set null,waiter_id uuid references public.comanda_staff(id) on delete set null,cash_session_id uuid references public.comanda_cash_sessions(id) on delete set null,opened_by uuid not null references auth.users(id) on delete restrict,diners integer not null default 1 check(diners>0 and diners<=200),label text,status text not null default 'open' check(status in('open','closed','cancelled')),cancellation_reason text,opened_at timestamptz not null default now(),closed_at timestamptz,updated_at timestamptz not null default now());
create unique index if not exists comanda_one_open_order_per_table on public.comanda_orders(table_id) where status='open' and table_id is not null;
create table if not exists public.comanda_order_items (id uuid primary key default gen_random_uuid(),account_id uuid not null references public.comanda_accounts(id) on delete cascade,order_id uuid not null references public.comanda_orders(id) on delete cascade,product_id uuid references public.comanda_products(id) on delete set null,product_name text not null,quantity numeric(10,2) not null default 1 check(quantity>0),unit_price numeric(14,2) not null default 0 check(unit_price>=0),notes text,destination text not null default 'kitchen' check(destination in('kitchen','bar','none')),kitchen_status text not null default 'draft' check(kitchen_status in('draft','pending','preparing','ready','delivered','cancelled')),sent_at timestamptz,prepared_at timestamptz,cancelled_at timestamptz,cancellation_reason text,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.comanda_payments (id uuid primary key default gen_random_uuid(),account_id uuid not null references public.comanda_accounts(id) on delete cascade,order_id uuid not null references public.comanda_orders(id) on delete cascade,cash_session_id uuid references public.comanda_cash_sessions(id) on delete set null,staff_id uuid references public.comanda_staff(id) on delete set null,method text not null check(method in('cash','pos','transfer','room_charge','other')),amount numeric(14,2) not null check(amount>0),received_amount numeric(14,2),change_amount numeric(14,2) not null default 0,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now());
create table if not exists public.comanda_audit_logs (id bigint generated always as identity primary key,account_id uuid not null references public.comanda_accounts(id) on delete cascade,branch_id uuid references public.comanda_branches(id) on delete set null,user_id uuid not null references auth.users(id) on delete restrict,staff_id uuid references public.comanda_staff(id) on delete set null,action text not null,entity_type text,entity_id uuid,detail jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.comanda_onboarding (account_id uuid primary key references public.comanda_accounts(id) on delete cascade,business_done boolean not null default false,team_done boolean not null default false,tables_done boolean not null default false,menu_done boolean not null default false,cash_done boolean not null default false,completed_at timestamptz,updated_at timestamptz not null default now());

create or replace function private.comanda_has_account_access(p_account_id uuid) returns boolean language sql stable security definer set search_path=pg_catalog,public as $$ select exists(select 1 from public.comanda_accounts a where a.id=p_account_id and a.owner_id=auth.uid()) or exists(select 1 from public.comanda_members m where m.account_id=p_account_id and m.user_id=auth.uid()); $$;
create or replace function private.comanda_is_account_admin(p_account_id uuid) returns boolean language sql stable security definer set search_path=pg_catalog,public as $$ select exists(select 1 from public.comanda_accounts a where a.id=p_account_id and a.owner_id=auth.uid()) or exists(select 1 from public.comanda_members m where m.account_id=p_account_id and m.user_id=auth.uid() and m.role in('owner','admin')); $$;
revoke all on function private.comanda_has_account_access(uuid) from public,anon; revoke all on function private.comanda_is_account_admin(uuid) from public,anon; grant execute on function private.comanda_has_account_access(uuid) to authenticated,service_role; grant execute on function private.comanda_is_account_admin(uuid) to authenticated,service_role;

create or replace function public.comanda_bootstrap_account(p_name text) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$
declare v_uid uuid:=auth.uid();v_account uuid;v_branch uuid;v_sector uuid;v_category uuid;v_slug text;
begin if v_uid is null then raise exception 'authentication_required'; end if; if length(trim(coalesce(p_name,'')))<2 then raise exception 'business_name_required';end if;
select id into v_account from public.comanda_accounts where owner_id=v_uid order by created_at limit 1;if v_account is not null then return v_account;end if;
v_slug:=lower(regexp_replace(unaccent(trim(p_name)),'[^a-zA-Z0-9]+','-','g'));v_slug:=trim(both '-' from v_slug)||'-'||substr(replace(gen_random_uuid()::text,'-',''),1,6);
insert into public.comanda_accounts(name,slug,owner_id) values(trim(p_name),v_slug,v_uid) returning id into v_account;insert into public.comanda_members(account_id,user_id,role) values(v_account,v_uid,'owner');
insert into public.comanda_branches(account_id,name) values(v_account,'Central') returning id into v_branch;insert into public.comanda_cash_registers(account_id,branch_id,name) values(v_account,v_branch,'Caja principal');
insert into public.comanda_staff(account_id,branch_id,name,staff_type,permissions) values(v_account,v_branch,'Administrador','admin','{"all":true}'),(v_account,v_branch,'Mozo eventual','waiter','{"sell":true,"open_table":true}'),(v_account,v_branch,'Cajero','cashier','{"sell":true,"take_payment":true,"cash":true}'),(v_account,v_branch,'Cocina','cook','{"kitchen":true}');
insert into public.comanda_sectors(account_id,branch_id,name,sort_order) values(v_account,v_branch,'Salón',1) returning id into v_sector;insert into public.comanda_tables(account_id,branch_id,sector_id,number,seats,pos_x,pos_y) select v_account,v_branch,v_sector,n::text,4,(n-1)%4,floor((n-1)/4.0)::int from generate_series(1,12)n;
insert into public.comanda_categories(account_id,branch_id,name,color,sort_order) values(v_account,v_branch,'Cafetería','#d8b07a',1),(v_account,v_branch,'Entradas','#8bd4b1',2),(v_account,v_branch,'Principales','#f0a8a8',3),(v_account,v_branch,'Bebidas','#91c9ef',4),(v_account,v_branch,'Postres','#e4c7a8',5);
select id into v_category from public.comanda_categories where account_id=v_account and name='Cafetería' limit 1;insert into public.comanda_products(account_id,category_id,name,price,destination,sort_order) values(v_account,v_category,'Café espresso',3000,'bar',1),(v_account,v_category,'Café americano',4000,'bar',2),(v_account,v_category,'Café con leche',5000,'bar',3),(v_account,v_category,'Medialuna',2000,'kitchen',4);
select id into v_category from public.comanda_categories where account_id=v_account and name='Principales' limit 1;insert into public.comanda_products(account_id,category_id,name,price,destination,sort_order) values(v_account,v_category,'Milanesa con papas',12500,'kitchen',1),(v_account,v_category,'Hamburguesa completa',11500,'kitchen',2),(v_account,v_category,'Pasta del día',10500,'kitchen',3),(v_account,v_category,'Ensalada completa',8500,'kitchen',4);
select id into v_category from public.comanda_categories where account_id=v_account and name='Bebidas' limit 1;insert into public.comanda_products(account_id,category_id,name,price,destination,sort_order) values(v_account,v_category,'Agua mineral',3000,'bar',1),(v_account,v_category,'Gaseosa',3500,'bar',2);
insert into public.comanda_onboarding(account_id,business_done,team_done,tables_done,menu_done,cash_done) values(v_account,true,true,true,true,true);return v_account;end;$$;
revoke all on function public.comanda_bootstrap_account(text) from public,anon;grant execute on function public.comanda_bootstrap_account(text) to authenticated;

do $$ declare t text; begin foreach t in array array['comanda_accounts','comanda_members','comanda_branches','comanda_staff','comanda_cash_registers','comanda_cash_sessions','comanda_sectors','comanda_tables','comanda_categories','comanda_products','comanda_orders','comanda_order_items','comanda_payments','comanda_audit_logs','comanda_onboarding'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy comanda_accounts_select on public.comanda_accounts for select to authenticated using(private.comanda_has_account_access(id));
create policy comanda_accounts_insert on public.comanda_accounts for insert to authenticated with check(owner_id=auth.uid());
create policy comanda_accounts_update on public.comanda_accounts for update to authenticated using(private.comanda_is_account_admin(id)) with check(private.comanda_is_account_admin(id));
create policy comanda_members_select on public.comanda_members for select to authenticated using(private.comanda_has_account_access(account_id));
create policy comanda_members_manage on public.comanda_members for all to authenticated using(private.comanda_is_account_admin(account_id)) with check(private.comanda_is_account_admin(account_id));
create policy comanda_branches_access on public.comanda_branches for all to authenticated using(private.comanda_has_account_access(account_id)) with check(private.comanda_has_account_access(account_id));
create policy comanda_staff_access on public.comanda_staff for all to authenticated using(private.comanda_has_account_access(account_id)) with check(private.comanda_has_account_access(account_id));
create policy comanda_cash_registers_access on public.comanda_cash_registers for all to authenticated using(private.comanda_has_account_access(account_id)) with check(private.comanda_has_account_access(account_id));
create policy comanda_cash_sessions_access on public.comanda_cash_sessions for all to authenticated using(private.comanda_has_account_access(account_id)) with check(private.comanda_has_account_access(account_id));
create policy comanda_sectors_access on public.comanda_sectors for all to authenticated using(private.comanda_has_account_access(account_id)) with check(private.comanda_has_account_access(account_id));
create policy comanda_tables_access on public.comanda_tables for all to authenticated using(private.comanda_has_account_access(account_id)) with check(private.comanda_has_account_access(account_id));
create policy comanda_categories_access on public.comanda_categories for all to authenticated using(private.comanda_has_account_access(account_id)) with check(private.comanda_has_account_access(account_id));
create policy comanda_products_access on public.comanda_products for all to authenticated using(private.comanda_has_account_access(account_id)) with check(private.comanda_has_account_access(account_id));
create policy comanda_orders_access on public.comanda_orders for all to authenticated using(private.comanda_has_account_access(account_id)) with check(private.comanda_has_account_access(account_id));
create policy comanda_order_items_access on public.comanda_order_items for all to authenticated using(private.comanda_has_account_access(account_id)) with check(private.comanda_has_account_access(account_id));
create policy comanda_payments_access on public.comanda_payments for all to authenticated using(private.comanda_has_account_access(account_id)) with check(private.comanda_has_account_access(account_id));
create policy comanda_audit_select on public.comanda_audit_logs for select to authenticated using(private.comanda_has_account_access(account_id));
create policy comanda_audit_insert on public.comanda_audit_logs for insert to authenticated with check(private.comanda_has_account_access(account_id) and user_id=auth.uid());
create policy comanda_onboarding_access on public.comanda_onboarding for all to authenticated using(private.comanda_has_account_access(account_id)) with check(private.comanda_has_account_access(account_id));
revoke all on public.comanda_accounts,public.comanda_members,public.comanda_branches,public.comanda_staff,public.comanda_cash_registers,public.comanda_cash_sessions,public.comanda_sectors,public.comanda_tables,public.comanda_categories,public.comanda_products,public.comanda_orders,public.comanda_order_items,public.comanda_payments,public.comanda_audit_logs,public.comanda_onboarding from anon;
grant select,insert,update,delete on public.comanda_accounts,public.comanda_members,public.comanda_branches,public.comanda_staff,public.comanda_cash_registers,public.comanda_cash_sessions,public.comanda_sectors,public.comanda_tables,public.comanda_categories,public.comanda_products,public.comanda_orders,public.comanda_order_items,public.comanda_payments,public.comanda_onboarding to authenticated;grant select,insert on public.comanda_audit_logs to authenticated;grant usage,select on sequence public.comanda_audit_logs_id_seq to authenticated;
do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='comanda_orders') then alter publication supabase_realtime add table public.comanda_orders;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='comanda_order_items') then alter publication supabase_realtime add table public.comanda_order_items;end if;end $$;